
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lcy_pbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lcy_pbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.009076326355391e+00, -3.926233920935400e+00, -3.810203323600297e+00, -3.649578921740891e+00, -3.430927665700697e+00, -3.140365956626555e+00, -2.767257495731864e+00, -2.310731948372226e+00, -1.787868121921815e+00, -1.237474296320682e+00, -7.283016123595242e-01, -4.718057699367165e-01, -3.982524011614272e-01, -2.893630301948816e-01, -1.584248770139347e-01, -5.357332714971264e-02, -7.623060652741327e-03, -3.153528226928156e-04, -3.064988893866026e-06, -4.275836133771552e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


